WITH matched_keys AS (SELECT order_id, carrier FROM shipments INTERSECT SELECT order_id, carrier FROM shipments WHERE status NOT IN ('IN_TRANSIT', 'RETURNED', 'LOST')), kept_rows AS (SELECT s.* FROM shipments s INNER JOIN matched_keys k ON s.order_id = k.order_id AND s.carrier = k.carrier) SELECT id, order_id, cost, status, CASE WHEN status RLIKE '^(LOST|RETURNED)$' THEN 'GROUP_B' ELSE 'CORE' END AS status_zone FROM kept_rows;
